<script setup lang="ts">import type { ArticleDetail } from '../../../shared/types/content'; const route = useRoute(); const { data: article } = await useFetch<ArticleDetail>(`/api/articles/${route.params.slug}`); if (!article.value) throw createError({ statusCode: 404, statusMessage: '找不到這篇文章' }); useSeoMeta({ title: () => article.value?.seoTitle || article.value?.title, description: () => article.value?.seoDescription || article.value?.excerpt, robots: () => article.value?.noIndex ? 'noindex, nofollow' : 'index, follow' })</script>
<template><article v-if="article" class="article-page"><NuxtLink to="/articles">← 返回靈感札記</NuxtLink><p class="eyebrow">{{ article.category }} · {{ article.publishedAt }}</p><h1>{{ article.title }}</h1><p class="article-intro">{{ article.excerpt }}</p><NotionContent v-if="article.blocks.length" class="prose" :blocks="article.blocks" /><div v-else class="prose"><p>文章內容準備中。</p></div></article></template>
